// Independent differential comparator: /output/test17.mjs vs the reference executable.
// Uses only the gold records captured earlier; does not trust any agent-authored harness.
import { spawnSync } from 'node:child_process';
import { readFileSync } from 'node:fs';

const gold = JSON.parse(readFileSync('/workspace/verify/gold/gold.json', 'utf8'));
const ENTRY = '/output/test17.mjs';

const normIat = (s) => s.replace(/'iat': \d+/g, "'iat': <IAT>");
const parts = (tok) => tok.trim().split('.');

let fail = 0, pass = 0;
const failures = [];

for (const rec of gold) {
  const r = spawnSync('node', [ENTRY, ...rec.argv], { encoding: 'utf8' });
  const problems = [];
  if (r.status !== rec.code) problems.push(`exit ${r.status} != ${rec.code}`);
  if (r.stderr !== rec.stderr) problems.push(`stderr:\n  py=${JSON.stringify(rec.stderr)}\n  js=${JSON.stringify(r.stderr)}`);
  if (rec.code === 0 && rec.stdout.includes('.')) {
    const gl = rec.stdout.split('\n'), jl = r.stdout.split('\n');
    if (gl.length !== jl.length) problems.push(`line count ${jl.length} != ${gl.length}`);
    // token: header must match exactly; payload/sig differ only via iat
    const gp = parts(gl[0] || ''), jp = parts(jl[0] || '');
    if (gp[0] !== jp[0]) problems.push(`header b64 differs: ${gp[0]} vs ${jp[0]}`);
    if (jp.length !== 3) problems.push(`token segments ${jp.length}`);
    if (normIat(gl[1] || '') !== normIat(jl[1] || '')) {
      problems.push(`line2:\n  py=${JSON.stringify(gl[1])}\n  js=${JSON.stringify(jl[1])}`);
    }
  } else if (r.stdout !== rec.stdout) {
    problems.push(`stdout:\n  py=${JSON.stringify(rec.stdout)}\n  js=${JSON.stringify(r.stdout)}`);
  }
  if (problems.length) { fail++; failures.push({ argv: rec.argv, problems }); } else pass++;
}

console.log(`behavioural: ${pass} pass, ${fail} fail`);
for (const f of failures.slice(0, 25)) {
  console.log('--- ARGV', JSON.stringify(f.argv));
  for (const p of f.problems) console.log('   ', p);
}
if (failures.length > 25) console.log(`... ${failures.length - 25} more`);
process.exit(fail ? 1 : 0);
EOF
