// Proves byte-identical tokens: take each reference token, extract its own iat + info,
// re-sign through /output/lib/jwt.mjs, require an exact string match.
import { readFileSync } from 'node:fs';
const gold = JSON.parse(readFileSync('/workspace/verify/gold/gold.json', 'utf8'));
const { encode } = await import('/output/lib/jwt.mjs');
const { base64UrlDecode } = await import('/output/lib/base64url.mjs');
const { utf8Decode } = await import('/output/lib/bytes.mjs');

let pass = 0, fail = 0;
for (const rec of gold) {
  if (rec.code !== 0 || !rec.stdout.includes('.')) continue;
  const refToken = rec.stdout.split('\n')[0];
  const payloadJson = utf8Decode(base64UrlDecode(refToken.split('.')[1]));
  const m = /"iat":(\d+)}$/.exec(payloadJson);
  const iat = Number(m[1]);
  const info = rec.argv[rec.argv.indexOf('--data') + 1];
  const claims = new Map([['info', info], ['iat', iat]]);
  const mine = encode(claims, 'secret');
  if (mine === refToken) pass++;
  else {
    fail++;
    if (fail <= 8) {
      console.log('MISMATCH for data=', JSON.stringify(info));
      console.log('  py:', refToken);
      console.log('  js:', mine);
      console.log('  pyPayloadJSON:', JSON.stringify(payloadJson));
    }
  }
}
console.log(`token identity: ${pass} exact, ${fail} mismatched`);
process.exit(fail ? 1 : 0);
EOF
